<div class="page-heading"><div><span class="section-kicker">ADMINISTRATION</span><h1>Security activity</h1><p>Authentication, permission and report events. Passwords, tokens and record contents are never shown here.</p></div></div><section class="card"><div class="card-body"><form action="<?= e(base_url('index.php')) ?>" method="get"><input type="hidden" name="page" value="security_activity"><?= select_field('category','Event category',['all'=>'All security events','auth'=>'Authentication','security'=>'Rejected requests','staff'=>'Staff access changes','report'=>'Reports'],$category,true) ?><button class="btn btn-outline-primary">Filter</button></form></div><div class="table-responsive"><table class="table"><thead><tr><th>Time (UTC)</th><th>Event</th><th>Staff</th><th>IP address</th><th>Records</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?= e(date_display($row['occurred_at'],true)) ?></td><td><?= e($row['action_code']) ?></td><td><?= e($row['actor']??'Unauthenticated') ?></td><td><?= e($row['ip']??'Not recorded') ?></td><td><?= $row['record_count']!==null?number((int)$row['record_count']):'—' ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5">No matching events.</td></tr><?php endif; ?></tbody></table></div><div class="card-body"><?= number($total) ?> events · Page <?= $p ?> of <?= $last ?> <?php if($p>1): ?><a class="btn btn-sm btn-light" href="<?= e(url('security_activity',['category'=>$category,'p'=>$p-1])) ?>">Previous</a><?php endif; ?> <?php if($p<$last): ?><a class="btn btn-sm btn-light" href="<?= e(url('security_activity',['category'=>$category,'p'=>$p+1])) ?>">Next</a><?php endif; ?></div></section>
